/**
 * WAPPY Canvas — Safe Markdown → HTML converter for SG-SST documents & reports.
 *
 * Designed specifically to handle mixed HTML (corporate banner headers, signature blocks)
 * + Markdown bodies generated by LLMs without breaking decimal/hierarchical headings
 * (e.g. "### 2.1. Objetivo General", "### 2.2. Objetivos Específicos", "### 3.1.2. Detalle")
 * and properly distinguishing ordered (<ol>) vs unordered (<ul>) lists.
 */

const findMatchingClosingTag = (html: string, startIndex: number, tagName: string): number => {
  const openTag = `<${tagName}`;
  const closeTag = `</${tagName}>`;
  let depth = 0;
  let i = startIndex;

  while (i < html.length) {
    if (html.slice(i, i + openTag.length).toLowerCase() === openTag) {
      depth++;
      i += openTag.length;
    } else if (html.slice(i, i + closeTag.length).toLowerCase() === closeTag) {
      depth--;
      if (depth === 0) {
        return i + closeTag.length;
      }
      i += closeTag.length;
    } else {
      i++;
    }
  }
  return -1;
};

const buildRichMediaBlock = (rawUrl: string, rawAlt = ''): string => {
  const cleanUrl = String(rawUrl || '')
    .trim()
    .replace(/^https?:\/\/(?:app\.)?wappy\.club(?=\/(?:images|api\/notebooklm\/download)\/)/i, '');
  const lower = cleanUrl.toLowerCase();
  const safeAlt = String(rawAlt || '')
    .replace(/<[^>]+>/g, '')
    .replace(/"/g, '&quot;')
    .trim();

  if (
    lower.includes('_audio_') ||
    lower.includes('_podcast_') ||
    lower.includes('type=audio') ||
    lower.includes('type=podcast') ||
    /\.(mp3|wav|m4a|ogg)(?:$|\?)/i.test(lower)
  ) {
    const label = safeAlt || 'Podcast / Audio Explicativo';
    return `<div style="margin:22px 0;padding:18px 22px;background:#f0fdfa;border:1px solid #99f6e4;border-radius:14px;box-shadow:0 4px 14px rgba(13,148,136,0.08);"><div style="font-weight:700;color:#0f766e;font-size:14px;margin-bottom:10px;">🎙️ ${label}</div><audio controls preload="metadata" src="${cleanUrl}" style="width:100%;display:block;"></audio><div style="margin-top:10px;font-size:12px;"><a href="${cleanUrl}" download target="_blank" rel="noopener noreferrer" style="color:#0d9488;font-weight:700;text-decoration:underline;">⬇ Descargar Audio / Podcast</a></div></div>`;
  }

  if (
    lower.includes('_vid_') ||
    lower.includes('_video_') ||
    lower.includes('type=video') ||
    lower.includes('type=cinematic_video') ||
    /\.(mp4|webm|mov)(?:$|\?)/i.test(lower)
  ) {
    const label = safeAlt || 'Video Explicativo';
    return `<figure style="margin:24px 0;text-align:center;background:#0f172a;padding:18px;border-radius:14px;border:1px solid #334155;box-shadow:0 8px 24px rgba(15,23,42,0.18);"><video controls playsinline preload="metadata" src="${cleanUrl}" style="max-width:100%;max-height:480px;border-radius:10px;background:#000;display:block;margin:0 auto;"></video><figcaption style="margin-top:10px;font-size:12px;color:#cbd5e1;font-weight:600;">🎬 ${label} · <a href="${cleanUrl}" download target="_blank" rel="noopener noreferrer" style="color:#2dd4bf;text-decoration:underline;">⬇ Descargar Video MP4</a></figcaption></figure>`;
  }

  if (
    lower.includes('_quiz_') ||
    lower.includes('_flashcards_') ||
    lower.includes('_mindmap_') ||
    lower.includes('_table_') ||
    lower.includes('_slides_') ||
    lower.includes('_report_') ||
    lower.includes('type=quiz') ||
    lower.includes('type=flashcards') ||
    lower.includes('type=mind_map') ||
    lower.includes('type=data_table') ||
    lower.includes('type=slide_deck') ||
    lower.includes('type=report') ||
    /\.(pdf|pptx|csv|md|markdown|json|docx|xlsx)(?:$|\?)/i.test(lower)
  ) {
    const label = safeAlt || 'Recurso / Documento Descargable';
    return `<div style="margin:18px 0;padding:16px 20px;background:#f8fafc;border:1px solid #cbd5e1;border-left:4px solid #0d9488;border-radius:12px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;"><div style="font-weight:700;color:#0f172a;font-size:13px;">📄 ${label}</div><a href="${cleanUrl}" download target="_blank" rel="noopener noreferrer" style="display:inline-block;padding:8px 14px;background:#0d9488;color:#ffffff;font-weight:700;font-size:12px;border-radius:8px;text-decoration:none;">⬇ Descargar Recurso</a></div>`;
  }

  const label = safeAlt || 'Infografía / Recurso Visual Oficial';
  return `<figure style="margin:24px 0;text-align:center;background:#f8fafc;padding:16px;border-radius:14px;border:1px solid #e2e8f0;"><img src="${cleanUrl}" alt="${label}" style="max-width:100%;height:auto;border-radius:10px;box-shadow:0 4px 20px rgba(15,23,42,0.08);display:block;margin:0 auto;" /><figcaption style="margin-top:10px;font-size:12px;color:#475569;font-style:italic;font-weight:600;">${label}</figcaption></figure>`;
};

const convertMarkdownMediaAndHealHtml = (input: string): string => {
  if (!input) return input;
  return input
    .replace(
      /<p>\s*!\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)\s*<\/p>/gi,
      (_, alt, url) => buildRichMediaBlock(url, alt),
    )
    .replace(
      /!\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g,
      (_, alt, url) => buildRichMediaBlock(url, alt),
    )
    .replace(
      /(?<![!">'=])\[([^\]]+)\]\(((?:https?:\/\/(?:app\.)?wappy\.club)?\/(?:images\/(?:flow_|nlm_|antigravity_|ag_|sst_)[^)\s]+|api\/notebooklm\/download\/[^)\s]+))\)/gi,
      (_, label, url) => buildRichMediaBlock(url, label),
    )
    .replace(
      /<p>\s*<em>\s*(<strong>[^<]+<\/strong>[\s\S]*?)<\/em>([^<*]+)\*([\s\S]*?)<\/p>/gi,
      (_, beforeEm, italicWord, afterWord) =>
        `<ul><li>${beforeEm}<em>${italicWord.trim()}</em>${afterWord}</li></ul>`,
    )
    .replace(/\*\*([^*\n<]+)\*(?!\*)/g, '<strong>$1</strong>')
    .replace(/(?<!\*)\*([^*\n<]+)\*\*/g, '<strong>$1</strong>')
    .replace(/<\/strong>\*/g, '</strong>')
    .replace(/<\/em>\*/g, '</em>');
};

/**
 * Formats inline Markdown (bold, italic, inline code, links, media) without
 * touching existing HTML tags or attribute values (such as base64 image data URLs).
 */
const formatInlineMarkdown = (text: string): string => {
  if (!text) return '';

  // 1. Convert inline markdown images & rich WAPPY download links first
  let out = text
    .replace(
      /!\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g,
      (_, alt, url) => buildRichMediaBlock(url, alt),
    )
    .replace(
      /(?<![!">'=])\[([^\]]+)\]\(((?:https?:\/\/(?:app\.)?wappy\.club)?\/(?:images\/(?:flow_|nlm_|antigravity_|ag_|sst_)[^)\s]+|api\/notebooklm\/download\/[^)\s]+))\)/gi,
      (_, label, url) => buildRichMediaBlock(url, label),
    )
    .replace(
      /(?<![!">'=])\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/gi,
      '<a href="$2" target="_blank" rel="noopener noreferrer" style="color:#004d99;text-decoration:underline;">$1</a>',
    );

  // 2. Apply emphasis/code formatting ONLY to text segments outside HTML tags
  const segments = out.split(/(<[^>]+>)/g);
  return segments
    .map((seg) => {
      if (!seg || seg.startsWith('<')) return seg;
      return seg
        .replace(
          /`([^`\n]+)`/g,
          '<code style="background:#f1f5f9;padding:1px 5px;border-radius:4px;font-size:0.9em;color:#0f172a;">$1</code>',
        )
        .replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
        .replace(/\*\*([^*\n]+)\*(?!\*)/g, '<strong>$1</strong>')
        .replace(/(?<!\*)\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
        .replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g, '<em>$1</em>');
    })
    .join('');
};

/**
 * Safe line-by-line normalization for genuinely glued ALL-CAPS section headings
 * (e.g. "(SURA)1. OBJETIVO" or "1. OBJETIVOEstablecer").
 *
 * STRICT GUARANTEES:
 * - NEVER splits lines starting with Markdown headings (#, ##, ###, ####, #####, ######).
 * - NEVER splits decimal/hierarchical numbering (2.1., 2.2., 3.1.2., 10.5).
 * - NEVER splits legal references (Res. 0312, Art. 25, Dec. 1072, Cap. 6).
 */
const normalizeSquishedLinesSafely = (markdownChunk: string): string => {
  const normalized = markdownChunk.replace(/\r\n?/g, '\n');
  const lines = normalized.split('\n');
  const outLines: string[] = [];

  for (const rawLine of lines) {
    const trimmed = rawLine.trim();

    // Never touch empty lines, Markdown headings, HTML lines, tables, blockquotes, or media lines
    if (
      !trimmed ||
      /^#{1,6}\s/.test(trimmed) ||
      trimmed.startsWith('<') ||
      trimmed.startsWith('|') ||
      trimmed.startsWith('>') ||
      trimmed.startsWith('![')
    ) {
      outLines.push(rawLine);
      continue;
    }

    let line = rawLine;

    // 1. Separate glued paragraph start right after an ALL-CAPS numbered heading
    //    (e.g. "1. OBJETIVOEstablecer..." -> "1. OBJETIVO\n\nEstablecer...")
    line = line.replace(
      /(\d+\.\s+[A-ZÁÉÍÓÚÑ]{2,})([A-ZÁÉÍÓÚÑ][a-záéíóúñ]{2,})/g,
      '$1\n\n$2',
    );

    // 2. Separate an ALL-CAPS numbered section genuinely glued to the end of preceding text
    //    (e.g. "(SURA)1. OBJETIVO" or "fin.2. ALCANCE"), NEVER after digits/decimals or abbreviations.
    line = line.replace(
      /(?<!\d)(?<!\b(?:Art|Res|Dec|Cap|Sec|Num|Nro|Inc|Lit|Par|No)\.)([a-záéíóúñ)\]»”".,;:])(\d+\.\s+[A-ZÁÉÍÓÚÑ]{2,}(?![A-Za-zÁÉÍÓÚÑáéíóúñ]))/g,
      (fullMatch, prevChar: string, headingStart: string, offset: number, wholeStr: string) => {
        // Extra safeguard against decimal numbers like "2.1. OBJETIVO" or "10.5. DETALLE"
        if (prevChar === '.' && offset > 0 && /\d/.test(wholeStr[offset - 1])) {
          return fullMatch;
        }
        return `${prevChar}\n\n${headingStart}`;
      },
    );

    outLines.push(line);
  }

  return outLines.join('\n');
};

/**
 * Parses a pure Markdown chunk (no outer HTML wrapper) into clean semantic HTML.
 */
const parseMarkdownChunk = (chunk: string): string => {
  const placeholders: string[] = [];
  const stashBlock = (html: string): string => {
    const token = `@@CANVAS_MD_BLOCK_${placeholders.length}@@`;
    placeholders.push(html);
    return `\n\n${token}\n\n`;
  };

  let working = chunk.replace(/\r\n?/g, '\n');

  // 1. Parse Markdown tables first and stash them as atomic HTML blocks
  const tableRegex =
    /((?:^|\n)\|[^\n]+\|[^\n]*\n\|[ \t]*:?-+:?[ \t]*\|[^\n]*\n(?:\|[^\n]+\|[^\n]*(?:\n|$))+)/g;
  working = working.replace(tableRegex, (match) => {
    const lines = match
      .trim()
      .split('\n')
      .map((l) => l.trim());
    if (lines.length < 2) return match;

    const headerCols = lines[0]
      .split('|')
      .map((c) => c.trim())
      .filter((_, i, arr) => i > 0 && i < arr.length - 1);
    const separatorCols = lines[1]
      .split('|')
      .map((c) => c.trim())
      .filter((_, i, arr) => i > 0 && i < arr.length - 1);

    const alignments = separatorCols.map((col) => {
      if (col.startsWith(':') && col.endsWith(':')) return 'center';
      if (col.endsWith(':')) return 'right';
      if (col.startsWith(':')) return 'left';
      return '';
    });

    const headersHtml = headerCols
      .map((col, idx) => {
        const align = alignments[idx] ? ` align="${alignments[idx]}"` : '';
        return `<th${align} style="border: 1px solid #ddd; padding: 8px; background-color: #f2f2f2; font-weight: bold; text-align: ${alignments[idx] || 'left'};">${formatInlineMarkdown(col)}</th>`;
      })
      .join('');

    const dataRowsHtml = lines
      .slice(2)
      .map((line) => {
        const cols = line
          .split('|')
          .map((c) => c.trim())
          .filter((_, i, arr) => i > 0 && i < arr.length - 1);
        const cellsHtml = cols
          .map((col, idx) => {
            const align = alignments[idx] ? ` align="${alignments[idx]}"` : '';
            return `<td${align} style="border: 1px solid #ddd; padding: 8px; text-align: ${alignments[idx] || 'left'};">${formatInlineMarkdown(col)}</td>`;
          })
          .join('');
        return `<tr>${cellsHtml}</tr>`;
      })
      .join('');

    const tableHtml =
      `<div style="overflow-x:auto; margin: 15px 0;"><table style="border-collapse: collapse; width: 100%; border: 1px solid #ddd; font-family: sans-serif; font-size: 13px;"><thead><tr>${headersHtml}</tr></thead><tbody>${dataRowsHtml}</tbody></table></div>`.replace(
        /\n/g,
        '',
      );
    return stashBlock(tableHtml);
  });

  // 2. Stash standalone Markdown image / rich-media lines so they are never wrapped in <p>
  working = working
    .replace(
      /^[ \t]*!\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)[ \t]*$/gm,
      (_, alt, url) => stashBlock(buildRichMediaBlock(url, alt)),
    )
    .replace(
      /^[ \t]*\[([^\]]+)\]\(((?:https?:\/\/(?:app\.)?wappy\.club)?\/(?:images\/(?:flow_|nlm_|antigravity_|ag_|sst_)[^)\s]+|api\/notebooklm\/download\/[^)\s]+))\)[ \t]*$/gim,
      (_, label, url) => stashBlock(buildRichMediaBlock(url, label)),
    );

  // 3. Safe line-by-line normalization for squished LLM headings
  working = normalizeSquishedLinesSafely(working);

  // 4. Deterministic line-by-line block parser (headings, hr, ul, ol, blockquote, paragraphs)
  const lines = working.split('\n');
  const htmlBlocks: string[] = [];

  let paragraphLines: string[] = [];
  let blockquoteLines: string[] = [];
  let activeListType: 'ul' | 'ol' | null = null;
  let activeListStart = 1;
  let activeListItems: string[] = [];

  const flushParagraph = () => {
    if (paragraphLines.length === 0) return;
    const joined = paragraphLines.map((l) => formatInlineMarkdown(l)).join('<br/>');
    htmlBlocks.push(`<p>${joined}</p>`);
    paragraphLines = [];
  };

  const flushBlockquote = () => {
    if (blockquoteLines.length === 0) return;
    const joined = blockquoteLines.map((l) => formatInlineMarkdown(l)).join('<br/>');
    htmlBlocks.push(
      `<blockquote style="border-left: 3px solid #004d99; padding: 6px 12px; margin: 10px 0; background: #f8fafc; color: #334155; font-style: italic;">${joined}</blockquote>`,
    );
    blockquoteLines = [];
  };

  const flushList = () => {
    if (!activeListType || activeListItems.length === 0) {
      activeListType = null;
      activeListItems = [];
      activeListStart = 1;
      return;
    }
    const itemsHtml = activeListItems.map((item) => `<li>${formatInlineMarkdown(item)}</li>`).join('');
    if (activeListType === 'ol') {
      const startAttr = activeListStart !== 1 ? ` start="${activeListStart}"` : '';
      htmlBlocks.push(`<ol${startAttr}>${itemsHtml}</ol>`);
    } else {
      htmlBlocks.push(`<ul>${itemsHtml}</ul>`);
    }
    activeListType = null;
    activeListItems = [];
    activeListStart = 1;
  };

  const flushAll = () => {
    flushParagraph();
    flushBlockquote();
    flushList();
  };

  for (const rawLine of lines) {
    const trimmed = rawLine.trim();

    // Blank line ends open blocks
    if (!trimmed) {
      flushAll();
      continue;
    }

    // Stashed atomic HTML block (table, figure, audio/video card)
    const placeholderMatch = trimmed.match(/^@@CANVAS_MD_BLOCK_(\d+)@@$/);
    if (placeholderMatch) {
      flushAll();
      const idx = Number(placeholderMatch[1]);
      if (placeholders[idx] !== undefined) {
        htmlBlocks.push(placeholders[idx]);
      }
      continue;
    }

    // Horizontal rule
    if (/^(?:---+|\*\*\*+|___+)$/.test(trimmed)) {
      flushAll();
      htmlBlocks.push('<hr/>');
      continue;
    }

    // Headings (# .. ######) — supports "### 2.1. Objetivo General", "### 2.1 Objetivo", "#### 3.1.2. Detalle"
    const headingMatch = trimmed.match(/^(#{1,6})\s+(.+?)(?:\s+#+)?$/);
    if (headingMatch) {
      flushAll();
      const level = headingMatch[1].length;
      const headingText = formatInlineMarkdown(headingMatch[2].trim());
      htmlBlocks.push(`<h${level}>${headingText}</h${level}>`);
      continue;
    }

    // Unordered list item (- item, * item, • item)
    const ulMatch = rawLine.match(/^\s*[-*•]\s+(.+)$/);
    if (ulMatch) {
      flushParagraph();
      flushBlockquote();
      if (activeListType !== 'ul') {
        flushList();
        activeListType = 'ul';
      }
      activeListItems.push(ulMatch[1].trim());
      continue;
    }

    // Ordered list item (1. item, 2. item, 3. item)
    const olMatch = rawLine.match(/^\s*(\d+)\.\s+(.+)$/);
    if (olMatch) {
      flushParagraph();
      flushBlockquote();
      const itemNumber = parseInt(olMatch[1], 10);
      if (activeListType !== 'ol') {
        flushList();
        activeListType = 'ol';
        activeListStart = Number.isFinite(itemNumber) && itemNumber > 0 ? itemNumber : 1;
      }
      activeListItems.push(olMatch[2].trim());
      continue;
    }

    // Blockquote (> quote)
    const bqMatch = rawLine.match(/^\s*>\s?(.*)$/);
    if (bqMatch) {
      flushParagraph();
      flushList();
      blockquoteLines.push(bqMatch[1].trim());
      continue;
    }

    // Pass-through block-level HTML line
    if (/^<(?:div|table|figure|hr|h[1-6]|ul|ol|blockquote|section|article|header|footer|p)[\s>/]/i.test(trimmed)) {
      flushAll();
      htmlBlocks.push(trimmed);
      continue;
    }

    // Standard paragraph line
    flushList();
    flushBlockquote();
    paragraphLines.push(trimmed);
  }

  flushAll();

  return convertMarkdownMediaAndHealHtml(htmlBlocks.join('\n'));
};

export function convertCanvasMarkdownToHtml(md: string): string {
  if (typeof md !== 'string' || !md) return String(md ?? '');

  // If it's already purely HTML (no markdown headers, bold, or rules), heal media and return as-is
  if (
    md.trim().startsWith('<') &&
    !md.includes('#') &&
    !md.includes('**') &&
    !md.includes('---')
  ) {
    return convertMarkdownMediaAndHealHtml(md);
  }

  let header = '';
  let body = md;
  let signature = '';

  // 1. Extract leading HTML header blocks (comments, corporate banner divs, metadata tables, style tags)
  let index = 0;
  while (index < md.length) {
    const remaining = md.substring(index);
    const nextCharMatch = remaining.search(/\S/);
    if (nextCharMatch === -1) break;
    const actualIndex = index + nextCharMatch;
    const actualRemaining = md.substring(actualIndex);

    if (actualRemaining.startsWith('<!--')) {
      const commentEnd = actualRemaining.indexOf('-->');
      if (commentEnd !== -1) {
        index = actualIndex + commentEnd + 3;
        continue;
      }
    } else if (
      actualRemaining.startsWith('<div') ||
      actualRemaining.startsWith('<table') ||
      actualRemaining.startsWith('<style')
    ) {
      const startTag = actualRemaining.startsWith('<div')
        ? 'div'
        : actualRemaining.startsWith('<table')
          ? 'table'
          : 'style';
      const endIndex = findMatchingClosingTag(md, actualIndex, startTag);
      if (endIndex !== -1) {
        index = endIndex;
        continue;
      }
    }
    break;
  }

  if (index > 0) {
    header = md.substring(0, index);
    body = md.substring(index);
  }

  // 2. Extract trailing Signature block if present
  const sigMarkers = [
    '<div style="margin-top: 60px;',
    '<div style="margin-top:60px;',
    '<div style="margin-top: 50px;',
    '<div style="margin-top:50px;',
    '<div style="page-break-inside:avoid;',
    '<div style="page-break-inside: avoid;',
    '<div class="signature-placeholder',
  ];

  let sigStartIndex = -1;
  for (const marker of sigMarkers) {
    const idx = body.lastIndexOf(marker);
    if (idx !== -1 && (sigStartIndex === -1 || idx < sigStartIndex)) {
      sigStartIndex = idx;
    }
  }

  if (sigStartIndex !== -1) {
    signature = body.substring(sigStartIndex);
    body = body.substring(0, sigStartIndex);
  }

  // 3. Split body into HTML blocks and Markdown blocks so existing HTML isn't re-parsed
  const parts = body.split(/(<div[\s\S]*?<\/div>|<table[\s\S]*?<\/table>|<figure[\s\S]*?<\/figure>)/i);

  const parsedBody = parts
    .map((part) => {
      if (!part) return '';
      if (part.trim().startsWith('<')) {
        return part;
      }
      return parseMarkdownChunk(part);
    })
    .join('');

  return convertMarkdownMediaAndHealHtml(header + parsedBody + signature);
}
